import re
from openpyxl import load_workbook
wb = load_workbook('/home/uctpiaj/work/extraction/providence-worcester.xlsx')
# scan all text cells for #NN references and validate they point to intended parties
rows = list(wb['Deal ledger'].iter_rows(min_row=2, values_only=True))
def who(n): return f"{rows[n-1][2]} / {rows[n-1][4]}"
refs = []
for sname in wb.sheetnames:
    for row in wb[sname].iter_rows(values_only=True):
        for v in row:
            if isinstance(v,str):
                refs += [(sname, m.group(0)) for m in re.finditer(r'#\d+', v)]
for s,r in sorted(set(refs)):
    n = int(r[1:])
    print(s, r, "->", who(n) if 1<=n<=len(rows) else "OUT OF RANGE")
EOF"}
